<script setup>
import { Head, Link, router, useForm } from '@inertiajs/vue3'
import { reactive, ref } from 'vue'
import AppLayout from '../../../Layouts/AppLayout.vue'
const props = defineProps({ users: Object, filters: Object, courses: Array })
const filters = reactive({ search: props.filters.search || '', role: props.filters.role || '', active: props.filters.active ?? '', sort: props.filters.sort || 'newest' })
const selected = ref([])
const enrollment = useForm({ user_ids: [], course_id: '', starts_at: '', ends_at: '' })
const labels = { ADMIN: 'مدیر', TEACHER: 'مدرس', STUDENT: 'هنرجو' }
const apply = () => router.get('/admin/users', filters, { preserveState: true, replace: true })
const setStatus = active => router.post('/admin/users/bulk/status', { user_ids: selected.value, active }, { onSuccess: () => selected.value = [] })
const enroll = () => { enrollment.user_ids = selected.value; enrollment.post('/admin/users/bulk/enroll', { onSuccess: () => selected.value = [] }) }
</script>
<template><AppLayout><Head title="مدیریت کاربران"/><div class="space-y-5">
<section class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h1 class="text-xl font-bold">کاربران</h1><div class="flex gap-2"><Link href="/admin/student-imports" class="rounded-xl border px-4 py-2 text-sm font-bold">ورود گروهی هنرجویان</Link><Link href="/admin/users/create" class="rounded-xl bg-teal-700 px-4 py-2 text-sm font-bold text-white">کاربر جدید</Link></div></div><form class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5" @submit.prevent="apply"><input v-model="filters.search" placeholder="نام، موبایل یا ایمیل"><select v-model="filters.role"><option value="">همه نقش‌ها</option><option value="ADMIN">مدیر</option><option value="TEACHER">مدرس</option><option value="STUDENT">هنرجو</option></select><select v-model="filters.active"><option value="">همه وضعیت‌ها</option><option value="1">فعال</option><option value="0">غیرفعال</option></select><select v-model="filters.sort"><option value="newest">جدیدترین</option><option value="oldest">قدیمی‌ترین</option><option value="name">نام</option></select><button class="rounded-xl border px-4 py-2">اعمال فیلتر</button></form></section>
<section v-if="selected.length" class="rounded-2xl border bg-white p-4"><p class="mb-3 font-bold">{{selected.length}} کاربر انتخاب شده</p><div class="flex flex-wrap gap-2"><button class="rounded-xl border px-4 py-2" @click="setStatus(true)">فعال‌سازی</button><button class="rounded-xl border border-red-300 px-4 py-2 text-red-700" @click="setStatus(false)">غیرفعال‌سازی</button><select v-model="enrollment.course_id"><option value="">انتخاب دوره</option><option v-for="course in courses" :key="course.id" :value="course.id">{{course.title}}</option></select><input v-model="enrollment.starts_at" type="date" title="تاریخ شروع"><input v-model="enrollment.ends_at" type="date" title="تاریخ پایان"><button :disabled="!enrollment.course_id" class="rounded-xl bg-teal-700 px-4 py-2 text-white disabled:opacity-40" @click="enroll">ثبت‌نام در دوره</button></div><p v-if="enrollment.hasErrors" class="mt-2 text-sm text-red-600">{{Object.values(enrollment.errors)[0]}}</p></section>
<section class="grid gap-3 sm:grid-cols-2"><article v-for="user in users.data" :key="user.id" class="rounded-2xl border bg-white p-4"><div class="flex items-start gap-3"><input v-model="selected" type="checkbox" :value="user.id" class="mt-4"><img v-if="user.avatar_url" :src="user.avatar_url" alt="" class="h-12 w-12 rounded-full object-cover"><div v-else class="grid h-12 w-12 place-items-center rounded-full bg-teal-50 font-bold text-teal-800">{{user.first_name?.[0]}}{{user.last_name?.[0]}}</div><div><Link :href="`/admin/users/${user.id}`" class="font-bold text-teal-800">{{user.name}}</Link><p class="text-sm text-slate-500">{{labels[user.role]}} · {{user.is_active?'فعال':'غیرفعال'}}</p></div></div><div class="mt-3 text-sm"><p dir="ltr" class="text-right">{{user.mobile}}</p><p>{{user.email||'بدون ایمیل'}}</p></div><div class="mt-3 flex gap-4 text-sm"><Link :href="`/admin/users/${user.id}`" class="text-teal-700">جزئیات</Link><Link :href="`/admin/users/${user.id}/edit`" class="text-teal-700">ویرایش</Link></div></article></section>
<div class="flex flex-wrap gap-2"><Link v-for="link in users.links" :key="link.label" :href="link.url||''" v-html="link.label" class="rounded-lg border px-3 py-1 text-sm" :class="{'bg-teal-700 text-white':link.active,'pointer-events-none opacity-40':!link.url}"/></div></div></AppLayout></template>
